class DateTimeEncoder(json.JSONEncoder):
    """自定义 JSON 编码器，处理 datetime 和 Path 对象。"""

    def default(self, obj):
        if isinstance(obj, datetime):
            return obj.isoformat()
        if isinstance(obj, Path):
            return str(obj)
        return super().default(obj)


def _convert_to_serializable(obj):
    """递归转换对象为可序列化格式。"""
    if obj is None:
        return None
    if isinstance(obj, datetime):
        return obj.isoformat()
    if isinstance(obj, Path):
        return str(obj)
    if hasattr(obj, "model_dump"):
        # Pydantic 模型
        return _convert_to_serializable(obj.model_dump())
    if isinstance(obj, dict):
        return {k: _convert_to_serializable(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple)):
        return [_convert_to_serializable(item) for item in obj]
    return obj


class StateCache:
    """处理状态缓存。

    用于支持中断后继续执行。

    Example:
        >>> state_cache = StateCache()
        >>> state_cache.save(state)
        >>> restored = state_cache.load("task_001")
    """

    def __init__(self, cache_dir: Optional[Path] = None) -> None:
        """初始化状态缓存。"""
        self.cache_dir = (cache_dir or settings.cache.cache_dir) / "states"
        self.cache_dir.mkdir(parents=True, exist_ok=True)

    def _get_state_path(self, task_id: str) -> Path:
        """获取状态文件路径。"""
        return self.cache_dir / f"{task_id}_state.json"

    def save(self, task_id: str, state: GraphState) -> None:
        """保存处理状态。"""
        state_path = self._get_state_path(task_id)

        # 递归转换所有对象为可序列化格式
        state_data = _convert_to_serializable(dict(state))

        with open(state_path, "w", encoding="utf-8") as f:
            json.dump(state_data, f, ensure_ascii=False, indent=2, cls=DateTimeEncoder)

        logger.debug(f"处理状态已保存 | task_id={task_id}")

